/** user-defined types **/

export type AiCreatedCommit = { sha: string; summary: string; description: string; files: string[] }
export type AiProviderStatus = { id: string; configured: boolean }
/**
 * One line of a file, tagged with the commit that last changed it.
 */
export type BlameLine = { line_no: number; text: string; sha: string; short_sha: string; summary: string; author_name: string; author_email: string; time: number }
export type BranchInfo = { name: string; is_head: boolean; upstream: string | null; ahead: number; behind: number; 
/**
 * Richer reading of the same relationship; prefer this over the raw counts.
 */
sync: SyncState; 
/**
 * Commit time of the branch tip, seconds since epoch.
 */
time: number | null; 
/**
 * Abbreviated tip sha, for display.
 */
tip: string | null }
export type BranchList = { local: BranchInfo[]; remote: string[] }
/**
 * How two arbitrary refs relate: commits `ours` has that `theirs` doesn't
 * (ahead) and commits `theirs` has that `ours` doesn't (behind).
 */
export type BranchRelation = { ahead: number; behind: number }
/**
 * A branch's link to an OpenSpec change, as the UI sees it.
 * 
 * Fields stay snake_case, matching every other type crossing this boundary.
 */
export type BranchSpecLink = { change_id: string; 
/**
 * True when the user linked this branch, false when it was read from
 * `Spec:` trailers. The UI words the two differently: an inferred link is
 * a guess the user can make explicit.
 */
explicit: boolean }
/**
 * What to do with uncommitted changes when switching branches.
 */
export type BranchSwitchMode = 
/**
 * Stash before switching, reapply after. A conflicting reapply leaves the
 * stash intact as a backup. Most protective; the default.
 */
"auto_stash" | 
/**
 * Plain `git checkout`: carry changes to the new branch, but refuse the
 * switch if any change would be overwritten.
 */
"carry" | 
/**
 * Refuse to switch while the working tree is dirty.
 */
"refuse"
export type BuildInfo = { version: string; build_date: string; git_hash: string; debug: boolean }
/**
 * A repository path paired with the icon GitWyrm already knows about, for
 * screens that list many repositories at once.
 */
export type CachedRepoIcon = { repo_path: string; data_url: string; custom: boolean }
export type CatalogModel = { id: string; name: string; 
/**
 * Whether the account can actually select this model. Always true for static
 * catalog entries; a live Copilot list marks plan-gated models false so the
 * picker can show them greyed out instead of hiding them.
 */
enabled: boolean }
export type CatalogProvider = { id: string; name: string; base_url: string; dialect: Dialect; models: CatalogModel[] }
/**
 * Where commit change size appears in the graph.
 */
export type ChangeSizeDisplay = 
/**
 * A compact Changes column beside the author.
 */
"column" | 
/**
 * A second line below each commit message.
 */
"row"
/**
 * A change's lifecycle state, derived from its tasks and deltas rather than
 * stored anywhere. One function owns the rules so both windows agree.
 */
export type ChangeStatus = 
/**
 * No tasks yet, or none done: still being written.
 */
"draft" | 
/**
 * Some tasks done, build work outstanding.
 */
"inBuild" | 
/**
 * Build groups are complete but a review/verify group is still open.
 */
"needsReview" | 
/**
 * Every task done and at least one delta: ready for `openspec archive`.
 */
"readyToArchive"
/**
 * What happened to uncommitted changes during a branch switch.
 */
export type CheckoutOutcome = 
/**
 * Tree was clean, or changes carried over cleanly. Nothing to report.
 */
"clean" | 
/**
 * Changes were stashed and popped back successfully.
 */
"stashed" | 
/**
 * Changes were stashed, the switch happened, but the pop conflicted. The
 * stash was KEPT as a backup; the working tree has conflict markers.
 */
"stash_pop_conflict" | 
/**
 * Changes were stashed and the switch happened, but re-applying them failed
 * for a reason other than conflicts. The stash was KEPT as a backup and the
 * working tree does NOT have the changes, so the user must be told where
 * their work went.
 */
"stash_not_reapplied"
/**
 * Whether the CLI is usable, and which version answered.
 */
export type CliInfo = { available: boolean; 
/**
 * Version string as reported, when we could get one.
 */
version: string | null; 
/**
 * How it is invoked, for the log and for Settings: "openspec" or "npx".
 */
invocation: string | null }
/**
 * The result of a validate or archive attempt.
 */
export type CliOutcome = 
/**
 * The command ran and reported success.
 */
{ kind: "ok"; output: string } | 
/**
 * The command ran and reported a problem. `output` is the CLI's own text,
 * shown as-is; the UI adds the plain-language framing around it.
 */
{ kind: "failed"; output: string } | 
/**
 * No CLI available. `hint` explains what to install, in plain words.
 */
{ kind: "cliMissing"; hint: string }
