export type StashInfo = { index: number; 
/**
 * Raw stash message as git stores it, e.g. "On develop: auto-stash before...".
 */
message: string; 
/**
 * Message with git's "On <branch>: " / "WIP on <branch>: " prefix stripped.
 */
summary: string; 
/**
 * Branch the stash was taken on, parsed from the message when present.
 */
branch: string | null; 
/**
 * Full sha of the stash commit itself.
 */
sha: string; 
/**
 * Full sha of the commit the stash was taken on (first parent); anchors the
 * stash to a row in the graph.
 */
base_sha: string; 
/**
 * Unix epoch seconds of the stash commit.
 */
time: number; files_changed: number; additions: number; deletions: number }
/**
 * Result of a stash-save attempt. A clean working tree is a no-op, not an error.
 */
export type StashOutcome = "stashed" | "nothing_to_stash"
export type StatusCode = "A" | "M" | "D" | "R" | "!"
/**
 * How a submodule's checked-out commit differs from the commit its parent repo
 * pins. `ahead`/`behind` are the workdir commit's position relative to the
 * recorded one.
 */
export type SubmoduleMove = { path: string; 
/**
 * Commit the parent repo records for this submodule.
 */
recorded_sha: string; 
/**
 * Commit the submodule is actually checked out at, if initialized.
 */
workdir_sha: string | null; 
/**
 * Commits the workdir is ahead of the recorded commit.
 */
ahead: number; 
/**
 * Commits the workdir is behind the recorded commit.
 */
behind: number; 
/**
 * False when the submodule has not been checked out (needs init).
 */
initialized: boolean }
/**
 * Where a submodule stands relative to the commit its parent pins.
 */
export type SubmoduleState = 
/**
 * Checked out at exactly the commit the parent records.
 */
"in_sync" | 
/**
 * Checked out, but at a different commit than the parent records.
 */
"moved" | 
/**
 * Recorded in .gitmodules but never checked out -- needs downloading.
 */
"uninitialized"
/**
 * A submodule and everything the UI needs to describe it: where it points,
 * where it came from, and whether it matches what the parent records.
 * 
 * Unlike [`SubmoduleMove`], which only covers submodules that are out of sync,
 * this describes every submodule in the repo including healthy ones.
 */
export type SubmoduleStatus = { 
/**
 * Path within the parent repo, e.g. "packages/core".
 */
path: string; 
/**
 * Name from .gitmodules, which can differ from the path.
 */
name: string; 
/**
 * Clone URL, when .gitmodules records one.
 */
url: string | null; 
/**
 * Branch this submodule follows, when configured. Bumping moves to this
 * branch's tip; with none set, the remote's default branch is used.
 */
branch: string | null; 
/**
 * Commit the parent repo records for this submodule.
 */
recorded_sha: string; 
/**
 * Commit the submodule is actually checked out at, if initialized.
 */
workdir_sha: string | null; 
/**
 * Commits the workdir is ahead of the recorded commit.
 */
ahead: number; 
/**
 * Commits the workdir is behind the recorded commit.
 */
behind: number; state: SubmoduleState }
/**
 * How a branch stands against the remote. Distinguishes the three cases the
 * old `(0, 0)` collapsed together: genuinely in sync, no upstream configured,
 * and an upstream whose ref could not be resolved.
 */
export type SyncState = 
/**
 * Tracking an upstream, tips match.
 */
{ kind: "in_sync" } | 
/**
 * Tracking an upstream and diverged. At least one of the counts is non-zero.
 */
{ kind: "diverged"; ahead: number; behind: number } | 
/**
 * No upstream configured. The branch has never been pushed anywhere.
 */
{ kind: "never_pushed" } | 
/**
 * An upstream is configured but its ref is missing, e.g. the remote branch
 * was deleted and the stale tracking ref has since been pruned.
 */
{ kind: "upstream_gone" }
/**
 * A named set of repository tabs. Repository paths are stable across app
 * restarts, unlike the in-memory repo ids assigned when a repository opens.
 */
export type TabGroupSetting = { id: string; name: string; color: string; collapsed?: boolean; repo_paths?: string[] }
export type TagInfo = { name: string; 
/**
 * Commit the tag points at, after peeling an annotated tag's wrapper object.
 */
target_sha: string; 
/**
 * Annotated tags carry an author and message; lightweight ones don't.
 */
annotated: boolean; 
/**
 * When the tag was made, as a Unix timestamp. An annotated tag reports the
 * tagger's time; a lightweight tag has no date of its own, so it reports the
 * time of the commit it points at.
 */
time: number }
/**
 * One repository's tag-setting overrides, keyed by repo path in `Settings`.
 * Each field is optional: `Some` overrides the app-wide default for that repo,
 * `None` (the default) means the repo follows the app-wide setting. Validated
 * on the frontend.
 */
export type TagOverrideSetting = { 
/**
 * Per-repo push default: "ask", "always", "never". None follows the app default.
 */
push_default?: string | null; 
/**
 * Per-repo default for the New Tag send box. None follows the app default.
 */
push_on_create?: boolean | null; 
/**
 * Per-repo default for the Delete Tag "also remove from the remote" box.
 * None follows the app default.
 */
delete_on_remote?: boolean | null }
/**
 * Result of asking to toggle a task.
 */
export type ToggleOutcome = 
/**
 * The checkbox was flipped and the file written.
 */
"toggled" | 
/**
 * The task was already in the requested state, so nothing was written.
 */
"alreadyThatWay" | 
/**
 * The line no longer holds a checkbox -- the file changed underneath us.
 * The caller re-reads rather than guessing.
 */
"lineMoved"
/**
 * Which git and gpg the app resolved, and where each came from. Drives the
 * "using the copy that came with GitWyrm" vs "using your own" line in Settings.
 */
export type ToolInfo = { program: string; source: ToolSource; version: string | null }
/**
 * Where a resolved executable came from. Surfaced in Settings so the user can
 * see whether they are on their own install or ours.
 */
export type ToolSource = 
/**
 * The path the user typed or browsed to in Settings.
 */
"configured" | 
/**
 * Found on PATH - a system install.
 */
"system" | 
/**
 * The copy shipped inside GitWyrm.
 */
"bundled" | 
/**
 * Not found anywhere.
 */
"missing"
export type TutorialRepo = { 
/**
 * Working directory to open as a tab.
 */
path: string; 
/**
 * The branch that has diverged from `main`, so the UI can point lessons at
 * it by name instead of guessing.
 */
feature_branch: string }
/**
 * A local tag the given remote does not have, along with whether the remote
 * already holds the commit it points at. Tags on commits the remote lacks
 * cannot be pushed on their own, so they are reported separately.
 */
export type UnpushedTag = { name: string; target_sha: string; 
/**
 * True when the tagged commit is already reachable from a remote-tracking
 * ref, so pushing the tag alone will succeed.
 */
commit_on_remote: boolean }
export type UpdateChannel = "stable" | "beta"
export type WorkingStatus = { staged: FileChange[]; unstaged: FileChange[] }

/** tauri-specta globals **/

import {
	invoke as TAURI_INVOKE,
	Channel as TAURI_CHANNEL,
} from "@tauri-apps/api/core";
import * as TAURI_API_EVENT from "@tauri-apps/api/event";
import { type WebviewWindow as __WebviewWindow__ } from "@tauri-apps/api/webviewWindow";

type __EventObj__<T> = {
	listen: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.listen<T>>;
	once: (
		cb: TAURI_API_EVENT.EventCallback<T>,
	) => ReturnType<typeof TAURI_API_EVENT.once<T>>;
	emit: null extends T
		? (payload?: T) => ReturnType<typeof TAURI_API_EVENT.emit>
		: (payload: T) => ReturnType<typeof TAURI_API_EVENT.emit>;
};

export type Result<T, E> =
	| { status: "ok"; data: T }
	| { status: "error"; error: E };

function __makeEvents__<T extends Record<string, any>>(
	mappings: Record<keyof T, string>,
) {
	return new Proxy(
		{} as unknown as {
			[K in keyof T]: __EventObj__<T[K]> & {
				(handle: __WebviewWindow__): __EventObj__<T[K]>;
			};
		},
		{
			get: (_, event) => {
				const name = mappings[event as keyof T];

				return new Proxy((() => {}) as any, {
					apply: (_, __, [window]: [__WebviewWindow__]) => ({
						listen: (arg: any) => window.listen(name, arg),
						once: (arg: any) => window.once(name, arg),
						emit: (arg: any) => window.emit(name, arg),
					}),
					get: (_, command: keyof __EventObj__<any>) => {
						switch (command) {
							case "listen":
								return (arg: any) => TAURI_API_EVENT.listen(name, arg);
							case "once":
								return (arg: any) => TAURI_API_EVENT.once(name, arg);
							case "emit":
								return (arg: any) => TAURI_API_EVENT.emit(name, arg);
						}
					},
				});
			},
		},
	);
}
